using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Identity;
namespace AcxiomCRM.Models;
public class AppUser:IdentityUser { [MaxLength(120)] public string DisplayName {get;set;}=""; public string? ManagerId {get;set;} }
public class OwnedRecord { public int Id {get;set;} public string OwnerId {get;set;}=""; public DateTime CreatedAt {get;set;}=DateTime.UtcNow; }
public class Customer:OwnedRecord { [Required,MaxLength(120)] public string Name {get;set;}="";[Required,EmailAddress,MaxLength(200)] public string Email {get;set;}="";[Required,RegularExpression(@"^[0-9]{10}$")] public string Phone {get;set;}="";[MaxLength(120)] public string CompanyName {get;set;}="";public string Address {get;set;}="";public string City {get;set;}="";public string State {get;set;}="";public string Status {get;set;}="Active";public string CustomerCode {get;set;}=""; }
public class Lead:OwnedRecord { [Required,MaxLength(120)] public string Name {get;set;}="";[EmailAddress] public string Email {get;set;}="";[RegularExpression(@"^$|^[0-9]{10}$")] public string Phone {get;set;}="";public string CompanyName {get;set;}="";public string Source {get;set;}="Website";[RegularExpression("New|Contacted|Qualified|Unqualified|Converted|Lost")] public string Status {get;set;}="New";public string Priority {get;set;}="Medium";[Range(0,1000000000)] public decimal ExpectedValue {get;set;} public string LeadCode {get;set;}="";public string Notes {get;set;}=""; }
public class Opportunity:OwnedRecord { [Required] public string Name {get;set;}="";[Range(1,int.MaxValue)] public int CustomerId {get;set;} public int? LeadId {get;set;} [Range(typeof(decimal),"0.01","100000000000")] public decimal Amount {get;set;} [Range(0,100)] public int Probability {get;set;} [Required] public DateTime ExpectedCloseDate {get;set;}=DateTime.Today.AddDays(7);[RegularExpression("Qualification|Proposal|Negotiation|Won|Lost")] public string Stage {get;set;}="Qualification";public string Status {get;set;}="Open";public string Notes {get;set;}=""; }
public class FollowUp:OwnedRecord { public int? CustomerId {get;set;} public int? LeadId {get;set;} public int? OpportunityId {get;set;} [Required] public string Subject {get;set;}="";public DateTime FollowUpDate {get;set;}=DateTime.Today.AddDays(1);public string FollowUpType {get;set;}="Call";[RegularExpression("Planned|Completed|Missed|Cancelled")] public string Status {get;set;}="Planned";public string Remarks {get;set;}=""; }
public class Activity:OwnedRecord { [Required] public string Subject {get;set;}="";[RegularExpression("Call|Meeting|Email|Task")] public string ActivityType {get;set;}="Call";public string Description {get;set;}="";public DateTime ActivityDate {get;set;}=DateTime.Today;public int? CustomerId {get;set;} public int? LeadId {get;set;} [RegularExpression("Pending|Completed|Cancelled")] public string Status {get;set;}="Pending"; }
public class AuditLog {public int Id {get;set;}public string UserId {get;set;}="";public string Action {get;set;}="";public string EntityName {get;set;}="";public string RecordId {get;set;}="";public string OldValue {get;set;}="";public string NewValue {get;set;}="";public DateTime CreatedAt {get;set;}=DateTime.UtcNow;public string IpAddress {get;set;}="";}
